begin;
create extension if not exists pgtap with schema extensions;
select plan(6);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000090','follow-up@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000090','Follow-up citations');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000090','10000000-0000-4000-8000-000000000090','owner',now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000090","role":"authenticated"}',true);
create temporary table ids(result jsonb);
insert into ids values(public.save_case_revision('20000000-0000-4000-8000-000000000090','{"title":"Canary","template":"product_delivery","outcome":"achieved","problem":"Canary","context":"Team","constraints":"No downtime","approach":"Canary","observedOutcome":"Released","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","sources":[],"conceptIds":[]}'));
select public.publish_case_revision((select (result->>'revisionId')::uuid from ids),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions,jsonb_each_text(content) where workspace_id='20000000-0000-4000-8000-000000000090' and key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
create temporary table snapshots as select value as item from public.read_knowledge_case('20000000-0000-4000-8000-000000000090',(select (result->>'caseId')::uuid from ids),(select (result->>'revisionId')::uuid from ids),array['approach'],1) value;
select public.create_conversation('20000000-0000-4000-8000-000000000090','30000000-0000-4000-8000-000000000090');
select public.create_conversation('20000000-0000-4000-8000-000000000090','30000000-0000-4000-8000-000000000091');
create temporary table state(name text primary key, id uuid);
insert into state values('turn1',public.save_conversation_turn('30000000-0000-4000-8000-000000000090','40000000-0000-4000-8000-000000000090','How can we release?','{"version":2,"message":"How can we release?","history":[]}'));
insert into state values('run1',(public.admit_conversation_analysis((select id from state where name='turn1'),'50000000-0000-4000-8000-000000000090',2,90000)->>'runId')::uuid);
select public.finish_analysis((select id from state where name='run1'),'complete',jsonb_build_object('version',2,'text','Use the canary [S:'||(select id from state where name='run1')||':1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select id from state where name='run1')||':1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null);
insert into state values('other_turn',public.save_conversation_turn('30000000-0000-4000-8000-000000000091','40000000-0000-4000-8000-000000000091','Elsewhere','{"version":2,"message":"Elsewhere","history":[]}'));
insert into state values('other_run',(public.admit_conversation_analysis((select id from state where name='other_turn'),'50000000-0000-4000-8000-000000000091',2,90000)->>'runId')::uuid);
select public.finish_analysis((select id from state where name='other_run'),'complete',jsonb_build_object('version',2,'text','Use the canary [S:'||(select id from state where name='other_run')||':1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select id from state where name='other_run')||':1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null);
insert into state values('turn2',public.save_conversation_turn('30000000-0000-4000-8000-000000000090','40000000-0000-4000-8000-000000000092','Shorter please','{"version":2,"message":"Shorter please","history":[]}',(select id from state where name='turn1')));
insert into state values('run2',(public.admit_conversation_analysis((select id from state where name='turn2'),'50000000-0000-4000-8000-000000000092',2,90000)->>'runId')::uuid);
select throws_ok($$select public.finish_analysis((select id from state where name='run2'),'complete',jsonb_build_object('version',2,'text','Canary [S:00000000-0000-4000-8000-000000000001:1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:00000000-0000-4000-8000-000000000001:1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null)$$,'P0001','Invalid citation','a marker no answer in the conversation issued is rejected');
select throws_ok($$select public.finish_analysis((select id from state where name='run2'),'complete',jsonb_build_object('version',2,'text','Canary [S:'||(select id from state where name='other_run')||':1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select id from state where name='other_run')||':1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null)$$,'P0001','Invalid citation','a marker from another conversation is rejected');
select throws_ok($$select public.finish_analysis((select id from state where name='run2'),'complete',jsonb_build_object('version',2,'text','Canary [S:'||(select id from state where name='run1')||':2]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select id from state where name='run1')||':2]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null)$$,'P0001','Invalid citation','a marker number the earlier answer never saved is rejected');
select isnt(public.finish_analysis((select id from state where name='run2'),'complete',jsonb_build_object('version',2,'text','Canary, shorter [S:'||(select id from state where name='run1')||':1]','citations',jsonb_build_array(jsonb_build_object('marker','[S:'||(select id from state where name='run1')||':1]','evidenceId',(select item->>'evidenceId' from snapshots)))),(select jsonb_agg(item) from snapshots),'',null),null::uuid,'a follow-up can cite a source an earlier answer in the conversation cited');
select is((select generated->'citations'->0->>'marker' from public.briefs where run_id=(select id from state where name='run2')),'[S:'||(select id from state where name='run1')||':1]','the saved citation keeps the marker of the answer that issued it');
select is((select status from public.analysis_runs where id=(select id from state where name='run2')),'complete','the follow-up run completes');
select * from finish();
rollback;
